(()=>{
const root=document.getElementById('infra-observer'),content=root.querySelector('#io-content'),core=window.InfraNetwork;
const hosts={'linux-app-01':[{name:'eth0',type:'物理以太网',ip:'10.20.1.11',mac:'02:42:AC:14:01:11',speed:1000,scale:1},{name:'eth1',type:'备份网络',ip:'10.30.1.11',mac:'02:42:AC:14:01:12',speed:1000,scale:2.2},{name:'docker0',type:'虚拟网桥',ip:'172.17.0.1',mac:'02:42:AC:11:00:01',speed:null,scale:.5}], 'win-ad-01':[{name:'Ethernet',type:'物理以太网',ip:'10.20.1.20',mac:'02:42:AC:14:01:20',speed:1000,scale:.25},{name:'Ethernet 2',type:'管理网络',ip:'10.40.1.20',mac:'02:42:AC:14:01:21',speed:1000,scale:.12}], 'pve-node-01':[{name:'eno1',type:'物理上联',ip:'无独立 IP',mac:'02:42:AC:14:02:10',speed:10000,scale:6},{name:'vmbr0',type:'虚拟网桥',ip:'10.20.2.10',mac:'02:42:AC:14:02:10',speed:null,scale:5.5}]};
let host='linux-app-01',iface=0,unit='Mbps',range=60,running=false,rows=[],seq=0,selected={},policies={};
const time=t=>new Date(t).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
function seed(){rows=[];seq=0;for(let i=0;i<900;i++){rows.push(core.generate(++seq,hosts[host][iface].scale,rows.at(-1)));} }
function currentRows(){const last=rows.at(-1).time;return rows.filter(r=>r.time>last-range*1000);}
function options(list,current){return list.map(x=>'<option'+(x===current?' selected':'')+'>'+x+'</option>').join('');}
function render(){const n=hosts[host][iface];content.innerHTML='<div class="page-heading"><div><div class="net-layout-label">NETWORK OBSERVABILITY</div><h2>网络接口</h2><div class="muted">逐接口观察真实统计口径 · 收发速率、历史记录与采样质量</div></div><div class="page-actions"><span class="pill">模拟数据</span><button id="net-play" class="main">'+(running?'暂停模拟':'开始每秒模拟')+'</button></div></div><section class="box"><div class="net-toolbar"><label>服务器<select id="net-host">'+options(Object.keys(hosts),host)+'</select></label><label>指定网络接口<select id="net-iface">'+options(hosts[host].map(x=>x.name),n.name)+'</select></label><label>时间范围<select id="net-range"><option value="60" '+(range===60?'selected':'')+'>最近 1 分钟</option><option value="300" '+(range===300?'selected':'')+'>最近 5 分钟</option><option value="900" '+(range===900?'selected':'')+'>最近 15 分钟</option></select></label><label>速率单位<select id="net-unit">'+options(['Mbps','MiB/s'],unit)+'</select></label></div><div class="net-identity"><span><span class="status-dot"></span><b>UP</b> / '+n.type+'</span><span>IP <b>'+n.ip+'</b></span><span>MAC <b>'+n.mac+'</b></span><span>链路 <b>'+(n.speed?n.speed+' Mbps':'未提供，不计算占比')+'</b></span><span>资源 ID <b>'+host+'/'+n.name+'/boot-demo</b></span></div></section><div class="stats net-cards"><section class="box"><div class="stat-label">↓ 接收速率 Rx<span class="stat-icon">↓</span></div><div class="value net-rx" id="net-rx"></div><div class="muted">当前采样窗口平均值</div></section><section class="box"><div class="stat-label">↑ 发送速率 Tx<span class="stat-icon">↑</span></div><div class="value net-tx" id="net-tx"></div><div class="muted">与接收独立统计</div></section><section class="box"><div class="stat-label">所选范围流量</div><div class="value" id="net-traffic"></div><div class="muted" id="net-total-note"></div></section><section class="box"><div class="stat-label">数据有效性</div><div class="value" id="net-quality"></div><div class="muted" id="net-quality-note"></div></section></div><div class="net-grid"><section class="box"><div class="panel-head"><div><h3>接口收发速率</h3><small id="net-chart-span"></small></div><div class="net-chart-title"><span><i class="legend-key"></i>接收</span><span><i class="legend-key mint"></i>发送</span></div></div><div id="net-chart"></div><div id="net-chart-summary"></div><div class="net-caption">曲线基于逐秒样本；采样间隔以记录为准。缺失时断线显示，不补零、不跨缺口连线。</div></section><section class="box"><div class="panel-head"><h3>准确性与及时性</h3><span class="pill">可核对</span></div><div id="net-facts" class="net-facts"></div><div class="net-caption">速率 = 字节增量 ÷ 实际间隔；当前展示为模拟样本，未测量真实网络或端到端延迟。</div><div class="tabs"><button id="net-gap">模拟缺失样本</button></div></section></div><section class="box net-records"><div class="panel-head"><div><h3>采样记录</h3><small>最近 8 条 · CSV 导出所选时间范围 · 包含原始计数器</small></div><button id="net-export">导出 CSV ↓</button></div><div class="wrap" id="net-table"></div><div class="net-caption">本次页面内存保留最多 1,800 条样本；切换机器或网卡重新加载模拟数据，刷新页面重置。</div></section><section class="box net-policy"><div class="panel-head"><div><h3>监控接口与记录策略</h3><small>为 '+host+' 指定需要监控的接口</small></div><span class="pill">配置草稿</span></div><div class="net-checks">'+hosts[host].map((x,i)=>'<label><input type="checkbox" data-net-monitor="'+i+'" '+((selected[host]||[0]).includes(i)?'checked':'')+'>'+x.name+' · '+x.type+'</label>').join('')+'</div><div class="net-policy-fields"><label>采样频率<select id="net-frequency"><option>1 秒</option><option>5 秒</option><option>10 秒</option></select></label><label>原始样本保留<select id="net-retain"><option>7 天</option><option>3 天</option><option>1 天</option></select></label><label>分钟汇总保留<select id="net-aggregate"><option>90 天</option><option>30 天</option></select></label></div><div class="row"><button id="net-save" class="main">保存监控草稿</button><span class="net-status">不下发 Agent，不写入 PostgreSQL</span></div><div id="net-msg" role="status" aria-live="polite"></div></section><div class="notice">物理网卡、Bond 和虚拟网桥可能承载同一份流量；按接口独立展示，不直接相加。链路占比仅在速率口径一致且链路速率已知时计算。</div>';const saved=policies[host];if(saved){for(const [id,value]of Object.entries(saved))content.querySelector('#'+id).value=value;}paint();}
function paint(){if(!content.querySelector('#net-rx'))return;const n=hosts[host][iface],last=rows.at(-1),slice=currentRows(),s=core.summary(slice,unit);const number=bytes=>(bytes/1048576).toFixed(1);content.querySelector('#net-rx').innerHTML=(last.status==='valid'?core.rate(last.rx,last.dt,unit).toFixed(2):'—')+'<small>'+unit+'</small>';content.querySelector('#net-tx').innerHTML=(last.status==='valid'?core.rate(last.tx,last.dt,unit).toFixed(2):'—')+'<small>'+unit+'</small>';content.querySelector('#net-traffic').innerHTML=number(s.rx)+'<small>MiB ↓</small>';content.querySelector('#net-total-note').textContent=number(s.tx)+' MiB ↑ · 仅有效窗口';content.querySelector('#net-quality').innerHTML=(s.count/slice.length*100).toFixed(1)+'<small>%</small>';content.querySelector('#net-quality-note').textContent=s.count+' 个有效 / '+s.missing+' 个缺失';content.querySelector('#net-chart-span').textContent=time(slice[0].time)+' – '+time(last.time)+' CST · '+unit;const age=running?'正在每秒生成':'已暂停 / 静态快照';const facts=[['当前模式',age],['最后采样',time(last.time)+' CST'],['实际间隔',last.dt+' ms'],['数据来源','本地模拟计数器'],['Rx 累计字节',last.rxTotal.toLocaleString()+' B'],['Tx 累计字节',last.txTotal.toLocaleString()+' B'],['当前样本状态',last.status==='valid'?'有效':'缺失 · 未补零'],['接收链路占比',n.speed&&last.status==='valid'?(core.rate(last.rx,last.dt)/n.speed*100).toFixed(2)+'%':'不适用'],['错误包 / 丢弃包','0 / 0（演示）'],['已保留样本',rows.length+' / 1800']];content.querySelector('#net-facts').innerHTML=facts.map(([k,v])=>'<div><span>'+k+'</span><b>'+v+'</b></div>').join('');content.querySelector('#net-chart-summary').innerHTML='<span>Rx 加权平均 <b>'+s.rxAvg.toFixed(2)+' '+unit+'</b></span><span>Tx 加权平均 <b>'+s.txAvg.toFixed(2)+' '+unit+'</b></span><span>Rx 单窗口峰值 <b>'+s.rxMax.toFixed(2)+' '+unit+'</b></span>';drawChart(slice);content.querySelector('#net-table').innerHTML='<table><thead><tr>'+['采样时间 CST','间隔 ms','Rx 增量 B','Tx 增量 B','Rx '+unit,'Tx '+unit,'状态'].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+slice.slice(-8).reverse().map(r=>'<tr><td>'+time(r.time)+'</td><td>'+r.dt+'</td><td>'+(r.status==='valid'?r.rx.toLocaleString():'—')+'</td><td>'+(r.status==='valid'?r.tx.toLocaleString():'—')+'</td><td>'+(r.status==='valid'?core.rate(r.rx,r.dt,unit).toFixed(3):'—')+'</td><td>'+(r.status==='valid'?core.rate(r.tx,r.dt,unit).toFixed(3):'—')+'</td><td><span class="state '+(r.status==='valid'?'':'warning')+'">'+(r.status==='valid'?'有效':'缺失')+'</span></td></tr>').join('')+'</tbody></table>';}
function drawChart(data){const target=content.querySelector('#net-chart');const width=Math.max(270,target.clientWidth||600),height=230,left=55,right=12,top=16,bottom=34;const valid=data.filter(x=>x.status==='valid'),max=Math.max(1,...valid.flatMap(r=>[core.rate(r.rx,r.dt,unit),core.rate(r.tx,r.dt,unit)]))*1.15;const start=data[0].time,end=data.at(-1).time;const x=t=>left+(t-start)/Math.max(1,end-start)*(width-left-right),y=v=>height-bottom-v/max*(height-top-bottom);let svg='<svg class="net-chart" viewBox="0 0 '+width+' '+height+'" role="img" aria-label="模拟网卡收发速率曲线，横轴采样时间，纵轴'+unit+'"><text x="5" y="12">'+unit+'</text>';for(let i=0;i<=4;i++){const v=max*i/4;svg+='<line x1="'+left+'" x2="'+(width-right)+'" y1="'+y(v)+'" y2="'+y(v)+'"/><text x="'+(left-8)+'" y="'+(y(v)+4)+'" text-anchor="end">'+v.toFixed(1)+'</text>';}for(const [field,color]of[['rx','#8072eb'],['tx','#44b79d']]){let d='',gap=true;for(const r of data){if(r.status!=='valid'){gap=true;continue;}d+=(gap?'M':'L')+x(r.time).toFixed(2)+','+y(core.rate(r[field],r.dt,unit)).toFixed(2)+' ';gap=false;}svg+='<path d="'+d+'" fill="none" stroke="'+color+'" stroke-width="2"/>';}for(let i=0;i<3;i++){const t=start+(end-start)*i/2;svg+='<text x="'+x(t)+'" y="'+(height-9)+'" text-anchor="'+(i===0?'start':i===2?'end':'middle')+'">'+time(t)+'</text>';}target.innerHTML=svg+'</svg>';}
seed();window.renderNetwork=render;
root.addEventListener('change',e=>{if(e.target.id==='net-host'){host=e.target.value;iface=0;seed();render();}if(e.target.id==='net-iface'){iface=hosts[host].findIndex(n=>n.name===e.target.value);seed();render();}if(e.target.id==='net-range'){range=Number(e.target.value);paint();}if(e.target.id==='net-unit'){unit=e.target.value;paint();}});
root.addEventListener('click',e=>{const id=e.target.closest('button')?.id;if(id==='net-play'){running=!running;e.target.textContent=running?'暂停模拟':'开始每秒模拟';paint();}if(id==='net-gap'){const r=core.generate(++seq,hosts[host][iface].scale,rows.at(-1));r.status='missing';rows.push(r);if(rows.length>1800)rows.shift();paint();}if(id==='net-save'){policies[host]=Object.fromEntries(['net-frequency','net-retain','net-aggregate'].map(id=>[id,content.querySelector('#'+id).value]));selected[host]=Array.from(content.querySelectorAll('[data-net-monitor]:checked')).map(x=>Number(x.dataset.netMonitor));content.querySelector('#net-msg').textContent='本次预览已保存：'+(selected[host].map(i=>hosts[host][i].name).join('、')||'未选择接口')+'；'+content.querySelector('#net-frequency').value+'采样，原始记录 '+content.querySelector('#net-retain').value+'，汇总 '+content.querySelector('#net-aggregate').value+'。未下发，演示生成频率仍为 1 秒。';}if(id==='net-export'){const blob=new Blob([core.csv(currentRows(),host,hosts[host][iface].name)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='SIMULATED-'+host+'-'+hosts[host][iface].name+'-network.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});
setInterval(()=>{if(!running||document.hidden||!content.querySelector('#net-rx'))return;rows.push(core.generate(++seq,hosts[host][iface].scale,rows.at(-1)));if(rows.length>1800)rows.shift();paint();},1000);
new ResizeObserver(()=>{if(content.querySelector('#net-chart'))drawChart(currentRows());}).observe(content);
if(location.hash==='#network')root.querySelector('nav [data-page="network"]').click();
})();
